Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"smartcities":{"t":"What makes a city ‘smart’","c":"A smart city uses sensors, data and digital technology to run services more efficiently and improve life for residents, for example by managing traffic lights according to traffic, monitoring air quality, cutting energy use and making it easier to deal with local government online. Cities such as Singapore, Seoul, Barcelona and Copenhagen are often cited as examples. Critics raise concerns about surveillance, privacy, cost and whether technology serves residents or the companies that sell it.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Smart traffic</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lights adjust to real-time traffic</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sensors</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Monitor air, water and noise</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Smart energy</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Efficient lighting and power grids</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Digital services</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pay, report and apply online</text></svg>","c":"Four common features"}]},"digitalid":{"t":"How digital IDs are used","c":"A national ID is an official document that proves who a person is, such as an identity card. Many countries are moving to digital IDs, which can be stored on phones and used to prove identity online. India’s Aadhaar, the world’s largest biometric ID system, covers over a billion people, and Estonia runs almost all public services online. Digital IDs can make it easier to open bank accounts and get benefits, but raise concerns about privacy, data breaches and people being excluded if the system fails.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Proving who you are</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Online and in person</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Banking</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Opening accounts and sending money</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Government services</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Benefits, taxes and voting</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Health</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Medical records and prescriptions</text></svg>","c":"Common uses"}]},"sulu":{"t":"The Sultanate of Sulu","c":"The Sultanate of Sulu was a Muslim state in the Sulu Archipelago of the southern Philippines, founded in the 15th century. At its height, it controlled trade routes across the Sulu Sea and parts of northern Borneo, trading pearls, sea cucumbers and other goods with China. It resisted Spanish conquest for over three centuries. In 1878, a sultan granted part of North Borneo to a British company, an agreement whose meaning is still disputed and underlies the Philippines’ claim to Sabah.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.1450s</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sultanate founded by Sharif ul-Hashim</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1600s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gains territory in northern Borneo</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1878</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Signs a North Borneo deal with a British firm</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1899</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bates Treaty with the United States</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1915</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sultan gives up political power</text></svg>","c":"Key dates of the sultanate"}]},"commonwealth":{"t":"The Philippine Commonwealth","c":"The Commonwealth of the Philippines was the government of the country from 1935 to 1946, a transition period before full independence from the United States. Under President Manuel L. Quezon, Filipinos ran their own internal affairs under a new constitution, while the US kept control of defence and foreign policy. A national language based on Tagalog was chosen. The Japanese invasion of 1941 forced the government into exile. Independence came on 4 July 1946.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1934</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">US Congress passes the Tydings–McDuffie Act</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">15 Nov 1935</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Commonwealth inaugurated; Quezon president</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1937</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tagalog chosen as basis of a national language</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 1941</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan invades</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1942–45</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Government in exile in the United States</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4 Jul 1946</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Independence</text></svg>","c":"From commonwealth to independence"}]},"quezon":{"t":"The Philippine Commonwealth","c":"The Commonwealth of the Philippines was the government of the country from 1935 to 1946, a transition period before full independence from the United States. Under President Manuel L. Quezon, Filipinos ran their own internal affairs under a new constitution, while the US kept control of defence and foreign policy. A national language based on Tagalog was chosen. The Japanese invasion of 1941 forced the government into exile. Independence came on 4 July 1946.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1934</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">US Congress passes the Tydings–McDuffie Act</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">15 Nov 1935</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Commonwealth inaugurated; Quezon president</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1937</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tagalog chosen as basis of a national language</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 1941</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan invades</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1942–45</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Government in exile in the United States</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4 Jul 1946</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Independence</text></svg>","c":"From commonwealth to independence"}]},"mabini":{"t":"Apolinario Mabini’s life","c":"Apolinario Mabini was a Filipino lawyer and political thinker, known as the ‘Brains of the Revolution’. Though paralysed from the waist down by illness in 1896, he became Emilio Aguinaldo’s chief adviser, drafting decrees and a constitution for the revolutionary government, and served as its first prime minister. Captured by the Americans, he was exiled to Guam for refusing to swear allegiance to the United States. He died of cholera soon after returning in 1903.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1864</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Tanauan, Batangas</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1896</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paralysed by illness</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1898</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Becomes Aguinaldo’s chief adviser</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1899</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First prime minister of the republic</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1901</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Exiled to Guam</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1903</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Returns and dies of cholera</text></svg>","c":"Key dates in Mabini’s life"}]},"aluna":{"t":"Antonio Luna’s life","c":"Antonio Luna was a Filipino scientist, journalist and general during the Philippine–American War. Trained as a pharmacist and chemist in Europe, where he joined the Propaganda Movement, he founded the newspaper La Independencia and set up a military academy. Known for his brilliance and fierce temper, he tried to impose strict discipline on the army, which made him enemies. He was killed by soldiers of the revolutionary army in Cabanatuan in June 1899. His brother was the painter Juan Luna.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1866</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Manila</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1890s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Studies science in Europe</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1898</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Founds La Independencia</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1899</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Leads Filipino forces against the Americans</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">5 Jun 1899</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Killed in Cabanatuan</text></svg>","c":"Key dates in Luna’s life"}]},"silang":{"t":"Gabriela Silang’s revolt","c":"Gabriela Silang was an Ilocana leader who continued the revolt against Spanish rule begun by her husband, Diego Silang, in the Ilocos region. After Diego was assassinated in 1763, she led the rebel forces for about four months, attacking the town of Vigan, before being captured and executed. She is remembered as one of the first women to lead a revolt in the Philippines, and the women’s organisation GABRIELA is named after her.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1731</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Ilocos</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1762</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diego Silang leads a revolt in Ilocos</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">May 1763</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diego is assassinated</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1763</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gabriela leads the revolt</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sep 1763</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Captured and executed</text></svg>","c":"A revolt in Ilocos, 1762–63"}]},"jesus":{"t":"The life of Jesus","c":"Jesus of Nazareth was a Jewish preacher and teacher in Roman-ruled Judea and Galilee in the 1st century, and the central figure of Christianity, whose followers believe he is the Son of God and the Messiah. Most of what is known about him comes from the four Gospels of the New Testament. He taught love of God and neighbour, often through parables, and was crucified in Jerusalem on the orders of the Roman governor Pontius Pilate. Christians believe he rose from the dead. In Islam, he is honoured as a prophet, Isa.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.4 BC</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Bethlehem, according to the Gospels</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Grows up</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">In Nazareth, Galilee</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.AD 28–30</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Teaches and heals around Galilee</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.AD 30–33</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crucified in Jerusalem</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 2.4 billion people are Christians</text></svg>","c":"His life as told in the Gospels (dates approximate)"}]},"muhammad":{"t":"The life of the Prophet Muhammad","c":"Muhammad was born in Mecca, in Arabia, around 570. Muslims believe he was the final prophet of God, to whom the Qur’an was revealed through the angel Gabriel over 23 years. Facing persecution in Mecca, he and his followers moved to Medina in 622, the Hijra, which marks the start of the Islamic calendar. By his death in 632, most of Arabia had accepted Islam. Out of respect, Muslims traditionally do not depict him in pictures, and say ‘peace be upon him’ after his name.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.570</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Mecca</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">610</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First revelation, in a cave near Mecca</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">622</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The Hijra: migration to Medina</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">630</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Returns to Mecca</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">632</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Medina</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 2 billion people are Muslims</text></svg>","c":"Key dates in his life"}]},"hokusai":{"t":"Katsushika Hokusai’s life","c":"Katsushika Hokusai was a Japanese artist and printmaker of the Edo period, and one of the most famous artists in the world. He produced around 30,000 works, including paintings, book illustrations and woodblock prints. His series ‘Thirty-six Views of Mount Fuji’, around 1831, includes ‘The Great Wave off Kanagawa’, one of the best-known images ever made. He used about 30 different names during his career and kept working into his late eighties. His art influenced European painters such as Monet and Van Gogh.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1760</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Edo (now Tokyo)</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1779</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Publishes his first prints</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1814</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First volume of his sketchbooks, the Hokusai Manga</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.1831</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thirty-six Views of Mount Fuji</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1849</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies, aged 88</text></svg>","c":"Key dates in Hokusai’s life"}]},"documentary":{"t":"Kinds of documentary film","c":"A documentary is a non-fiction film that records real life, people and events, to inform, persuade or preserve a record. Early examples include ‘Nanook of the North’ (1922). Lightweight cameras in the 1960s let filmmakers follow events as they happened, and streaming has made documentaries more popular than ever. Even documentaries involve choices about what to film, include and leave out, so viewers are encouraged to think about the filmmaker’s point of view.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Expository</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A narrator explains a topic</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Observational</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The camera quietly follows events</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Participatory</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The filmmaker takes part and interviews</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Poetic</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Images and mood more than facts</text></svg>","c":"Four common styles"}]},"inequality":{"t":"Measuring inequality","c":"Poverty means lacking enough money to meet basic needs such as food, clean water, shelter, health care and education. Extreme poverty has fallen dramatically since 1990, but hundreds of millions of people, many in sub-Saharan Africa, still live on less than about three US dollars a day. Inequality is about how unevenly income and wealth are shared. Economists often show it with a Lorenz curve: the further the curve sags below the line of perfect equality, the more unequal the society, measured by the Gini coefficient from 0 (equal) to 1. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 290\" width=\"600\" height=\"290\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:580px;max-width:100%;height:auto\"><line x1=\"80\" y1=\"250\" x2=\"380\" y2=\"250\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"80\" y1=\"250\" x2=\"80\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M80,250L380,30\" stroke=\"#16a34a\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><path d=\"M80,250C200,240 300,200 380,30\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/><path d=\"M80,250L380,30C300,200 200,240 80,250Z\" fill=\"#dc2626\" fill-opacity=\".15\"/><text x=\"230\" y=\"276\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Share of people, poorest to richest →</text><text x=\"56\" y=\"140\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" text-anchor=\"middle\" transform=\"rotate(-90 56 140)\">Share of income →</text><text x=\"250\" y=\"104\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#16a34a\" font-family=\"system-ui,sans-serif\">Perfect equality</text><text x=\"320\" y=\"206\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#dc2626\" font-family=\"system-ui,sans-serif\">Real country</text><text x=\"420\" y=\"150\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shaded gap = inequality</text><text x=\"420\" y=\"170\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bigger gap, higher</text><text x=\"420\" y=\"188\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gini coefficient</text></svg>","c":"A Lorenz curve (simplified)"}]},"overtourism":{"t":"Overtourism and responses","c":"Overtourism happens when so many visitors come to a place that it harms the environment, the quality of life of residents or the visitor experience itself. Popular cities, islands and natural sites from Venice and Barcelona to Kyoto and Bali have seen protests by residents. Places have responded with entry fees, visitor limits, bans on new hotels or holiday rentals and campaigns to spread tourists out. Since 2024, for example, Venice has charged day-trippers on busy days.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crowds</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Packed streets and sites</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f97316\" fill-opacity=\".2\" stroke=\"#f97316\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rising rents</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Homes turned into holiday rentals</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Damage</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Litter, erosion and stressed wildlife</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Entry fees and caps</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Limit numbers at busy times</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spread visitors out</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Promote off-season and lesser-known places</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rules for rentals</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Limit short-term lets</text></svg>","c":"Problems (top) and common responses"}]},"volunteering":{"t":"Ways to volunteer","c":"Volunteering means giving time and effort to help others or a cause, without being paid. Volunteers run food banks, coach sports, care for the environment, teach, help in hospitals, respond to disasters and more. The United Nations estimates that hundreds of millions of people volunteer each year, much of it informally, by helping neighbours. Volunteering benefits communities and can improve volunteers’ own wellbeing, skills and friendships. International Volunteer Day is 5 December.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Community</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Food banks, clean-ups, helping neighbours</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Education</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tutoring and mentoring</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Health and care</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hospitals and elderly care</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f97316\" fill-opacity=\".2\" stroke=\"#f97316\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Disaster relief</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rescue, shelter and supplies</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#15803d\" fill-opacity=\".2\" stroke=\"#15803d\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Environment</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tree planting and wildlife</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Online</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Translating, mapping and research</text></svg>","c":"Six ways people help"}]},"automation":{"t":"Which work is easiest to automate?","c":"Automation means using machines and computer systems to do work that people once did. It began with factory machines and has spread to robots, self-service checkouts and software. Artificial intelligence is now automating some office and creative tasks. Automation can raise productivity and remove dangerous or dull work, but can also eliminate jobs, so retraining and education are important. History suggests new kinds of jobs also appear, though not always for the same people.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Easier to automate</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Repetitive, predictable, rule-based tasks</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f97316\" fill-opacity=\".2\" stroke=\"#f97316\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Examples</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Data entry, assembly lines, routine checks</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Harder to automate</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Care, creativity and judgement</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Examples</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nursing, plumbing, teaching, research</text></svg>","c":"Tasks, not whole jobs, are usually automated"}]},"ubi":{"t":"The four features of universal basic income","c":"Universal basic income is the idea that governments should give every adult a regular cash payment, whether or not they work, enough to cover basic needs. Supporters say it would reduce poverty, simplify welfare and give security as automation changes work. Critics say it would be very expensive, could discourage work and would give money to people who do not need it. Trials have taken place in Finland, Kenya, the United States and elsewhere, with mixed and debated results.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Universal</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paid to everyone</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Unconditional</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">No need to work or look for work</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Regular</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paid at set intervals, such as monthly</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cash</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spent however people choose</text></svg>","c":"What makes it different from other welfare"}]},"onlinelearning":{"t":"Ways of learning online","c":"Online learning means studying through the internet, from full degree programmes to short videos and language apps. During the COVID-19 pandemic in 2020, schools in most countries closed, and over a billion students switched to learning from home, revealing big gaps in access to devices and internet. Online learning offers flexibility and reaches people far from schools, but many learners find it harder to stay motivated and miss face-to-face contact.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Live classes</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Everyone joins at the same time</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Self-paced courses</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Watch and work when you like</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">MOOCs</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Free or cheap courses for thousands</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blended learning</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Part online, part in class</text></svg>","c":"Four common formats"}]},"mentalyouth":{"t":"Young people and mental health","c":"Adolescence is a time of big changes, and many mental health conditions begin then: the World Health Organization says half of all mental health conditions start by age 14, though most cases go undetected and untreated. Stress at school, bullying, family problems, poverty and, for some, heavy social media use can affect young people’s wellbeing. Sleep, exercise, friendships, trusted adults and early support all help protect mental health.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Half by 14</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Half of conditions start by age 14 (WHO)</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Common struggles</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Anxiety, depression and stress</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">What helps</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sleep, exercise, friends, time offline</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ask for help</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Talk to a parent, teacher or counsellor</text></svg>","c":"Mental health in the teenage years"}]},"memes":{"t":"The life cycle of a meme","c":"An internet meme is an idea, joke, image, video or phrase that spreads rapidly online, usually changing as people copy and remix it. The word ‘meme’ was coined by biologist Richard Dawkins in 1976 for any idea that spreads from person to person. Memes can be silly, clever or political, and brands and campaigns now use them. Because they spread so quickly, memes can also carry misinformation.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1. Created</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">An image, clip or phrase is posted</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2. Shared</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">It spreads across apps and sites</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3. Remixed</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">People add their own versions</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4. Fades</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">It becomes old news, or a classic</text></svg>","c":"How a meme spreads and fades"}]},"esports":{"t":"Popular kinds of esports","c":"Esports are organised, competitive video gaming, often between professional teams, watched by millions online and in packed arenas. Top tournaments offer prize money in the millions of dollars. Esports are especially popular in South Korea and China, and have spread worldwide. They were a medal event at the 2022 Asian Games, held in 2023, and the International Olympic Committee has run its own esports events. Concerns include long training hours and player wellbeing.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Battle arenas (MOBAs)</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Two teams of five destroy each other’s base</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shooters</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Teams compete in first-person combat</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Battle royale</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Last player or team standing wins</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fighting games</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">One-on-one duels</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sports games</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Football, basketball and racing</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Strategy</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Build, plan and outthink opponents</text></svg>","c":"Six common types"}]},"kdrama":{"t":"What makes a Korean drama","c":"Korean dramas, or K-dramas, are television series from South Korea, part of the ‘Korean Wave’ (Hallyu) of popular culture that also includes K-pop and films. They are known for tightly plotted stories, often in a single season of around 16 episodes, mixing romance, comedy, family drama, history, fantasy and thrillers. Streaming services have made them hugely popular across Asia and the world; ‘Squid Game’ (2021) became one of Netflix’s most-watched series ever.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">One season</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Often about 16 episodes, with an ending</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Many genres</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romance, history, fantasy, thrillers</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Soundtracks</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Songs by popular singers</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Global fans</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Subtitled in dozens of languages</text></svg>","c":"Common features"}]},"shortvideo":{"t":"Vertical versus horizontal video","c":"Short-video apps let people watch and create clips usually lasting from a few seconds to a few minutes, filmed vertically to fill a phone screen. Viewers swipe from one video to the next, while algorithms learn what each person watches and serve more of it. The format has created new trends, music hits and careers. Concerns include how much time people spend on them, effects on attention and young people’s wellbeing, misinformation and data privacy. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 330\" width=\"620\" height=\"330\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:560px;max-width:100%;height:auto\"><rect x=\"60\" y=\"25\" width=\"140\" height=\"250\" rx=\"14\" fill=\"#1e293b\"/><rect x=\"68\" y=\"33\" width=\"124\" height=\"234\" rx=\"8\" fill=\"#c4b5fd\"/><text x=\"130\" y=\"300\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vertical (9:16)</text><text x=\"130\" y=\"318\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Short-video apps</text><rect x=\"280\" y=\"70\" width=\"280\" height=\"160\" rx=\"14\" fill=\"#1e293b\"/><rect x=\"288\" y=\"78\" width=\"264\" height=\"144\" rx=\"8\" fill=\"#bfdbfe\"/><text x=\"420\" y=\"300\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Horizontal (16:9)</text><text x=\"420\" y=\"318\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">TV, films, older videos</text><path d=\"M130,130l-14,-20h28z\" fill=\"#5b21b6\"/><path d=\"M130,170l-14,20h28z\" fill=\"#5b21b6\"/><text x=\"130\" y=\"156\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#3b0764\" font-family=\"system-ui,sans-serif\">Swipe</text></svg>","c":"Short-video apps fill the phone screen upright (simplified)"}]},"superhero":{"t":"Superheroes through the decades","c":"Superheroes are fictional characters with extraordinary powers or abilities who fight evil, usually with a secret identity and a distinctive costume. They began in American comic books in the late 1930s and spread into television, cartoons, games and films. Heroes have also come from Japan, with masked heroes and giant robots, and from many other countries’ comics. Since the 2000s, superhero films have become some of the highest-earning movies in history.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1938</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The first costumed superhero comic books (USA)</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1940s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Golden Age of comics; heroes in wartime</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Heroes with flaws and everyday problems</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1966</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japanese TV heroes and giant robots appear</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2000s–</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Superhero films become global hits</text></svg>","c":"How the genre grew"}]},"cosplay":{"t":"What goes into cosplay","c":"Cosplay, short for ‘costume play’, is dressing up as a character from anime, manga, comics, films, games or books, often with homemade costumes, wigs, make-up and props. The term was coined in 1984 by Japanese writer Nobuyuki Takahashi after visiting a science fiction convention in the United States. Cosplayers gather at fan conventions, take part in contests and share photos online. Many see it as a creative art form and a way to make friends.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Costume</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sewn, bought or adapted</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Props</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Made from foam, plastic or 3D printing</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wigs and make-up</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">To match the character</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Performance</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Poses and acting in character</text></svg>","c":"Four parts of a cosplay"}]},"phbio":{"t":"Some of the Philippines’ unique wildlife","c":"The Philippines is one of the world’s 17 ‘megadiverse’ countries, home to a huge share of Earth’s plant and animal species. Because its more than 7,600 islands were isolated for so long, many species live nowhere else, especially mammals, birds, reptiles and plants. It is also a biodiversity hotspot, meaning much of this life is threatened, mainly by forest loss. Protected areas such as Tubbataha Reefs and the Puerto Princesa Underground River help conserve it.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine eagle</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">One of the world’s largest eagles</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#78350f\" fill-opacity=\".2\" stroke=\"#78350f\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine tarsier</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tiny primate with huge eyes</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tamaraw</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Small buffalo found only on Mindoro</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rafflesia</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Giant flowers, several species endemic</text></svg>","c":"Four species found only in the Philippines"}]},"magsaysay":{"t":"Ramon Magsaysay’s life","c":"Ramon Magsaysay was the seventh president of the Philippines, serving from 1953 until his death in 1957. As defence secretary, he led the campaign against the communist Hukbalahap rebellion, combining military action with land and amnesty offers. As president, he was hugely popular for opening the presidential palace to ordinary people and travelling to the provinces. He died when his plane crashed on Mount Manunggal in Cebu. The Ramon Magsaysay Award, often called Asia’s Nobel Prize, is named after him.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1907</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Iba, Zambales</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1950</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Becomes defence secretary</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1953</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Elected president</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mar 1957</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in a plane crash in Cebu</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1957</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ramon Magsaysay Award established</text></svg>","c":"Key dates in Magsaysay’s life"}]},"delpilar":{"t":"Marcelo H. del Pilar’s life","c":"Marcelo H. del Pilar was a Filipino lawyer, journalist and leader of the Propaganda Movement, which campaigned peacefully for reforms under Spanish rule. Writing in Tagalog and Spanish, he criticised the power of the friars. He co-founded the newspaper Diariong Tagalog and, after moving to Spain in 1888, became editor of La Solidaridad, the movement’s main newspaper. He died of tuberculosis in Barcelona in 1896, shortly before the revolution began.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1850</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Bulakan, Bulacan</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1882</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Co-founds Diariong Tagalog</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1888</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Leaves for Spain</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1889</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Becomes editor of La Solidaridad</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1896</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Barcelona</text></svg>","c":"Key dates in del Pilar’s life"}]},"sora":{"t":"Tandang Sora’s life","c":"Melchora Aquino, known as Tandang Sora, was a Filipino revolutionary heroine called the ‘Mother of the Katipunan’. When the revolution began in 1896, she was already 84 years old, but she fed, sheltered and nursed wounded Katipuneros at her store and home. Arrested by the Spanish, she refused to give information and was exiled to the Mariana Islands. She returned after the Americans took over, and died in 1919 at the age of 107.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1812</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Caloocan</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aug 1896</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Helps the Katipunan, aged 84</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1896</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arrested and exiled to the Marianas</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1903</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Returns to the Philippines</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1919</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies, aged 107</text></svg>","c":"Key dates in Tandang Sora’s life"}]},"lorenzoruiz":{"t":"San Lorenzo Ruiz’s life","c":"Lorenzo Ruiz was the first Filipino saint. Born in Binondo, Manila, to a Chinese father and a Filipina mother, he was a calligrapher for the Dominican church. In 1636, accused of a crime, he sailed with Dominican missionaries to Japan, where Christianity was banned. They were arrested and tortured, and Ruiz was martyred in Nagasaki in 1637 for refusing to renounce his faith. He was beatified in Manila in 1981, the first beatification held outside the Vatican, and canonised in 1987.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c.1600</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Binondo, Manila</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1636</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sails to Japan with missionaries</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1637</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Martyred in Nagasaki</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1981</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Beatified in Manila</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#2563eb\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1987</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Canonised: the first Filipino saint</text></svg>","c":"Key dates in his life"}]},"fedelmundo":{"t":"Fe del Mundo’s life","c":"Fe del Mundo was a Filipino paediatrician and National Scientist who devoted over 80 years to children’s health. She is often said to have been the first woman admitted to Harvard Medical School’s paediatrics programme, in 1936. In 1957, she founded the first paediatric hospital in the Philippines, now the Fe del Mundo Medical Center. She did research on jaundice, dengue and other childhood diseases and promoted immunisation and family planning in rural areas.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1911</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Manila</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1933</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graduates in medicine, top of her class</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1936</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Studies paediatrics at Harvard</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1957</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Founds the first children’s hospital</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1980</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Named National Scientist</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2011</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies, aged 99</text></svg>","c":"Key dates in her life"}]},"jluna":{"t":"Juan Luna’s life","c":"Juan Luna was a Filipino painter, one of the first internationally recognised Filipino artists. His huge painting ‘Spoliarium’, showing fallen gladiators being dragged from a Roman arena, won a gold medal at the Madrid Exposition of Fine Arts in 1884, a triumph celebrated by Filipino reformists as proof of their equality with Europeans. It now hangs in the National Museum in Manila. He later supported the revolution and was a diplomat for the Philippine Republic. His brother was General Antonio Luna.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1857</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Badoc, Ilocos Norte</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1884</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spoliarium wins a gold medal in Madrid</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1890s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lives and paints in Paris</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1898</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diplomat for the revolutionary government</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1899</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Hong Kong</text></svg>","c":"Key dates in Juan Luna’s life"}]},"balagtas":{"t":"Francisco Balagtas’s life","c":"Francisco Balagtas, also known as Francisco Baltazar, was a Filipino poet, considered one of the greatest writers in Tagalog. His masterpiece, ‘Florante at Laura’ (1838), is a long metrical romance set in Albania, widely read as a hidden criticism of Spanish rule. It has been studied in Philippine schools for generations. The Balagtasan, a debate in verse, is named in his honour, and the Philippines celebrates Balagtas Day on 2 April, his birthday.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1788</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Panginay, Bulacan</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1830s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Imprisoned after a rivalry over a woman</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1838</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Florante at Laura is published</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1862</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Udyong, Bataan</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1924</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The first Balagtasan is held</text></svg>","c":"Key dates in Balagtas’s life"}]},"salonga":{"t":"Lea Salonga’s career","c":"Lea Salonga is a Filipino singer and actress, famous worldwide for her roles in musical theatre. At 18, she won the lead role of Kim in the musical ‘Miss Saigon’ in London, then on Broadway, winning a Tony Award in 1991, the first Asian woman to do so. She provided the singing voice of two Disney princesses, Jasmine in ‘Aladdin’ and Mulan, and was named a Disney Legend in 2011. She has also starred in ‘Les Misérables’ on Broadway.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1971</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Manila</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1989</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stars in Miss Saigon in London</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1991</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wins a Tony Award on Broadway</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1992</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Jasmine’s singing voice in Aladdin</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1998</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mulan’s singing voice</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2011</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Named a Disney Legend</text></svg>","c":"Key moments in her career"}]}});
